const abortError = () => new DOMException("Speech playback cancelled.", "AbortError");

type Playback = {
  reader: ReadableStreamDefaultReader<Uint8Array>;
  sources: Set<AudioBufferSourceNode>;
  reject: (error: unknown) => void;
  removeAbort: () => void;
